1	//! Prompt mode: prompts, compiled on demand from Piton, are sent to a local
2	//! coding harness as tasks, and each task's output is shown until it finishes.
3	//!
4	//! The latest task heads the view: its status as a coloured label, the hidden
5	//! anchor it was compiled from, and the compiled prompt the harness received.
6	//! Its output fills the space beneath, one table row per thing the harness
7	//! did (its text, each tool call, any error), with the kind of each as a
8	//! badge. A small row, always shown above the header, expands into a scrollable
9	//! accordion of every task sent, each of which opens onto its own output. A file opened
10	//! from the project tree splits the view, taking half of its width; the chat
11	//! input is never split.
12	//!
13	//! Prompts sent while the harness works wait in a queue, saved with the
14	//! project (see [`crate::prompt_queue`]), listed in the header under the task.
15	//!
16	//! Every task is saved with the project too (see [`crate::prompt_history`]),
17	//! and opening the project brings back the tasks sent before.
18	
19	use std::cell::Cell;
20	use std::path::{Path, PathBuf};
21	use std::rc::Rc;
22	
23	use anyhow::Result;
24	use futures::StreamExt as _;
25	use gpui_kit::assets::IconName;
26	use gpui_kit::base::ElementExt as _;
27	use gpui_kit::component::accordion::Accordion;
28	use gpui_kit::component::button::{Button, ButtonVariants as _};
29	use gpui_kit::component::label::Label;
30	use gpui_kit::component::notification::Notification;
31	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
32	use gpui_kit::component::spinner::Spinner;
33	use gpui_kit::component::switch::Switch;
34	use gpui_kit::component::table::{Table, TableBody, TableCell, TableHead, TableHeader, TableRow};
35	use gpui_kit::component::tag::Tag;
36	use gpui_kit::component::text::{TextView, TextViewStyle};
37	use gpui_kit::component::{
38	    ActiveTheme as _, ColorName, Icon, Sizable as _, StyledExt as _, h_flex, v_flex,
39	};
40	use gpui_kit::component::{Disableable as _, WindowExt as _};
41	use gpui_kit::prelude::FluentBuilder as _;
42	use gpui_kit::*;
43	
44	use crate::chat_input::{ChatInput, SendMode, Submit};
45	use crate::file_view::{CloseFile, FileView, OpenDefinition};
46	use crate::harness::{self, HarnessEvent};
47	use crate::harness_run::{HarnessRun, HarnessRuns};
48	use crate::hidden_anchor::{self, HiddenAnchor};
49	use crate::markdown;
50	use crate::project_directory::ProjectDirectory;
51	use crate::prompt_history::{self, RunRecord, SavedPrompt};
52	use crate::prompt_queue::{self, QueuedPrompt};
53	use crate::shell_format;
54	
55	/// The share of the width an opened file takes from the task view.
56	const FILE_SHARE: f32 = 0.5;
57	
58	/// The narrowest either side of the file split can be dragged.
59	const MIN_SPLIT_WIDTH: Pixels = px(160.);
60	
61	/// The tallest the expanded queue gets before it scrolls.
62	const MAX_QUEUE_HEIGHT: Pixels = px(240.);
63	
64	/// The tallest the compiled prompt in the header gets before it scrolls.
65	const MAX_PROMPT_HEIGHT: Pixels = px(160.);
66	
67	/// The widths of the output table's badge and status columns; the detail
68	/// column takes the rest.
69	const KIND_WIDTH: Pixels = px(130.);
70	const STATUS_WIDTH: Pixels = px(110.);
71	
72	/// A prompt in the queue. Its hidden anchor is resolved and saved in the
73	/// background just after it is queued; until then it cannot be sent.
74	struct QueueItem {
75	    id: usize,
76	    text: SharedString,
77	    saved: Option<QueuedPrompt>,
78	}
79	
80	/// A prompt on its way to the harness.
81	enum Sending {
82	    /// Typed and sent straight away, in a mode.
83	    Now(SendMode),
84	    /// Out of the queue, saved with its anchor.
85	    Queued(QueuedPrompt),
86	}
87	
88	/// A prompt sent to the harness, and what the harness did with it.
89	struct PromptTask {
90	    /// The prompt as typed, shown until it compiles.
91	    text: SharedString,
92	    compiled: Option<Compiled>,
93	    reply: Reply,
94	    status: TaskStatus,
95	}
96	
97	/// A sent prompt once compiled.
98	struct Compiled {
99	    /// The name of the hidden anchor it was compiled from.
100	    anchor: SharedString,
101	    markdown: String,
102	}
103	
104	#[derive(Clone, Copy, Debug, PartialEq)]
105	enum TaskStatus {
106	    Compiling,
107	    Running,
108	    Done,
109	    Failed,
110	    /// From the history, with no record of what came of it.
111	    Unrecorded,
112	}
113	
114	impl TaskStatus {
115	    fn label(self) -> &'static str {
116	        match self {
117	            Self::Compiling => "Compiling",
118	            Self::Running => "Running",
119	            Self::Done => "Done",
120	            Self::Failed => "Failed",
121	            Self::Unrecorded => "Not recorded",
122	        }
123	    }
124	
125	    fn is_active(self) -> bool {
126	        matches!(self, Self::Compiling | Self::Running)
127	    }
128	
129	    /// A label in the status's colour, with the status spelled out. Uses the
130	    /// palette colours, like the output badges, as the theme's solid status
131	    /// colours are unreadable in dark mode.
132	    fn tag(self) -> Tag {
133	        Tag::color(match self {
134	            Self::Compiling => ColorName::Cyan,
135	            Self::Running => ColorName::Yellow,
136	            Self::Done => ColorName::Green,
137	            Self::Failed => ColorName::Red,
138	            Self::Unrecorded => ColorName::Gray,
139	        })
140	        .text_sm()
141	        .child(self.label())
142	    }
143	}
144	
145	impl PromptTask {
146	    fn new(text: SharedString) -> Self {
147	        Self {
148	            text,
149	            compiled: None,
150	            reply: Reply::default(),
151	            status: TaskStatus::Compiling,
152	        }
153	    }
154	
155	    /// A task from the history, as it ended: its run's output is replayed
156	    /// through the harness's parser.
157	    fn restore(saved: SavedPrompt) -> Self {
158	        let mut task = Self::new(saved.text.into());
159	        let Some(record) = saved.record else {
160	            task.reply.done = true;
161	            task.status = TaskStatus::Unrecorded;
162	            return task;
163	        };
164	        if let Some(markdown) = record.user_prompt {
165	            task.set_compiled(Compiled {
166	                anchor: saved.anchor.name().to_string().into(),
167	                markdown,
168	            });
169	        }
170	        for event in record.output.iter().flat_map(harness::parse) {
171	            task.apply(event);
172	        }
173	        if let Some(error) = record.error {
174	            task.apply(HarnessEvent::Failed(error));
175	        }
176	        task.end();
177	        task
178	    }
179	
180	    fn set_compiled(&mut self, compiled: Compiled) {
181	        self.compiled = Some(compiled);
182	        self.status = TaskStatus::Running;
183	    }
184	
185	    /// Folds a harness event into the task's output and status.
186	    fn apply(&mut self, event: HarnessEvent) {
187	        match self.reply.apply(event) {
188	            Some(error) => self.fail(error),
189	            None if self.reply.done && self.status == TaskStatus::Running => {
190	                self.status = TaskStatus::Done
191	            }
192	            None => {}
193	        }
194	    }
195	
196	    fn fail(&mut self, error: String) {
197	        self.reply.parts.push(ReplyPart::Error(error));
198	        self.status = TaskStatus::Failed;
199	    }
200	
201	    /// The run is over. One that ended without a result, as when the harness
202	    /// was stopped, failed, and nothing still running in it finished.
203	    fn end(&mut self) {
204	        if self.reply.done {
205	            return;
206	        }
207	        self.reply.done = true;
208	        self.reply.settle_tools(ToolState::Failed);
209	        if self.status != TaskStatus::Failed {
210	            self.fail("The harness stopped without a result.".into());
211	        }
212	    }
213	}
214	
215	/// A harness reply as it streams in.
216	#[derive(Default)]
217	pub(crate) struct Reply {
218	    parts: Vec<ReplyPart>,
219	    done: bool,
220	}
221	
222	enum ReplyPart {
223	    Text(String),
224	    Tool(ToolCall),
225	    Error(String),
226	}
227	
228	#[derive(Debug, PartialEq)]
229	struct ToolCall {
230	    id: String,
231	    name: String,
232	    summary: Option<String>,
233	    state: ToolState,
234	}
235	
236	impl ToolCall {
237	    /// The tool's name, for the output column. Left out when the badge already
238	    /// says what the tool is and there is a summary to show instead; a tool
239	    /// the badge only calls "Tool" keeps its name.
240	    fn shown_name(&self) -> Option<&str> {
241	        let named_by_badge = ToolKind::of(&self.name) != ToolKind::Other;
242	        (!named_by_badge || self.summary.is_none()).then_some(self.name.as_str())
243	    }
244	}
245	
246	#[derive(Clone, Copy, Debug, PartialEq)]
247	enum ToolState {
248	    Running,
249	    Done,
250	    Failed,
251	}
252	
253	impl ToolState {
254	    fn label(self) -> &'static str {
255	        match self {
256	            Self::Running => "running",
257	            Self::Done => "done",
258	            Self::Failed => "failed",
259	        }
260	    }
261	}
262	
263	/// The general type of a tool call, shown as its badge.
264	#[derive(Clone, Copy, Debug, PartialEq)]
265	enum ToolKind {
266	    Read,
267	    Edit,
268	    Command,
269	    Web,
270	    Agent,
271	    Other,
272	}
273	
274	impl ToolKind {
275	    fn of(tool_name: &str) -> Self {
276	        match tool_name {
277	            "Read" | "Glob" | "Grep" | "LS" | "NotebookRead" => Self::Read,
278	            "Edit" | "MultiEdit" | "Write" | "NotebookEdit" => Self::Edit,
279	            "Bash" | "BashOutput" | "KillShell" | "KillBash" => Self::Command,
280	            "WebFetch" | "WebSearch" => Self::Web,
281	            "Task" | "Agent" => Self::Agent,
282	            _ => Self::Other,
283	        }
284	    }
285	
286	    fn label(self) -> &'static str {
287	        match self {
288	            Self::Read => "Files",
289	            Self::Edit => "Edit",
290	            Self::Command => "Command",
291	            Self::Web => "Web",
292	            Self::Agent => "Agent",
293	            Self::Other => "Tool",
294	        }
295	    }
296	
297	    fn icon(self) -> IconName {
298	        match self {
299	            Self::Read => IconName::BookOpen,
300	            Self::Edit => IconName::FilePenLine,
301	            Self::Command => IconName::SquareTerminal,
302	            Self::Web => IconName::Globe,
303	            Self::Agent => IconName::Bot,
304	            Self::Other => IconName::Wrench,
305	        }
306	    }
307	
308	    fn color(self) -> ColorName {
309	        match self {
310	            Self::Read => ColorName::Sky,
311	            Self::Edit => ColorName::Amber,
312	            Self::Command => ColorName::Violet,
313	            Self::Web => ColorName::Teal,
314	            Self::Agent => ColorName::Pink,
315	            Self::Other => ColorName::Gray,
316	        }
317	    }
318	}
319	
320	/// A row of a task's output table.
321	#[derive(Debug, PartialEq)]
322	enum OutputRow<'a> {
323	    Text(&'a str),
324	    Tool(&'a ToolCall),
325	    Error(&'a str),
326	}
327	
328	impl OutputRow<'_> {
329	    /// The kind of the row, as a badge in its own colour.
330	    fn badge(&self) -> Tag {
331	        let (tag, icon, label) = match self {
332	            Self::Text(_) => (Tag::secondary(), IconName::MessageSquare, "Reply"),
333	            Self::Tool(call) => {
334	                let kind = ToolKind::of(&call.name);
335	                (Tag::color(kind.color()), kind.icon(), kind.label())
336	            }
337	            Self::Error(_) => (Tag::danger(), IconName::TriangleAlert, "Error"),
338	        };
339	        tag.text_sm().child(
340	            h_flex()
341	                .gap_1()
342	                .child(Icon::new(icon).xsmall())
343	                .child(label),
344	        )
345	    }
346	}
