1345	/// `code` as a fenced markdown code block, its fence longer than any run of
1346	/// backticks inside it.
1347	fn code_block(language: &str, code: &str) -> String {
1348	    let longest = code.split(|c| c != '`').map(str::len).max().unwrap_or(0);
1349	    let fence = "`".repeat(longest.max(2) + 1);
1350	    format!("{fence}{language}\n{code}\n{fence}")
1351	}
