1353	/// `text` with the project directory written relative to it: paths inside the
1354	/// directory lose its path, and the directory itself reads `.`. A path that
1355	/// only starts with the same characters, like a sibling directory, is kept.
1356	fn relative_to_project(text: &str, project_dir: Option<&Path>) -> String {
1357	    let Some(dir) = project_dir
1358	        .and_then(Path::to_str)
1359	        .map(|dir| dir.trim_end_matches('/'))
1360	        .filter(|dir| !dir.is_empty())
1361	    else {
1362	        return text.to_string();
1363	    };
1364	    let is_path_char = |c: char| c.is_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | '~');
1365	    let ends_path = |rest: &str| rest.chars().next().is_none_or(|c| !is_path_char(c));
1366	
1367	    let mut out = String::with_capacity(text.len());
1368	    let mut rest = text;
1369	    while let Some(at) = rest.find(dir) {
1370	        out.push_str(&rest[..at]);
1371	        let after = &rest[at + dir.len()..];
1372	        let starts_path = out.chars().last().is_none_or(|c| !is_path_char(c));
1373	        rest = if starts_path && ends_path(after) {
1374	            out.push('.');
1375	            after
1376	        } else if starts_path && after.starts_with('/') {
1377	            let inside = &after[1..];
1378	            if ends_path(inside) {
1379	                out.push('.');
1380	            }
1381	            inside
1382	        } else {
1383	            out.push_str(dir);
1384	            after
1385	        };
1386	    }
1387	    out.push_str(rest);
1388	    out
1389	}
