        window.press("escape", cx);
    })
    .unwrap();
    cx.run_until_parked();

    cx.update_window(handle, |_, window, cx| {
        assert!(
            !chat.read(cx).is_focused(window, cx),
            "Esc left focus in the chat input"
        );
        window.input("hi", cx);
    })
    .unwrap();
    cx.run_until_parked();
    cx.update(|cx| assert_eq!(chat.read(cx).value(cx).as_ref(), ""));
}

