            Self::Files => "Search files…",
            Self::System => "Search the application's commands…",
            Self::Commands => "Search the harness's commands…",
            Self::Skills => "Search skills…",
            Self::Agents => "Search agents…",
        }
    }

    fn icon(self) -> IconName {
